type Result = { columns:string[]; values:unknown[][] };
type Status = { kind:"idle"|"good"|"bad"|"run"; text:string; rawError?:string };
type Group = { id:string;name:string;code:string;created_at?:number };
type Student = { id:string;name:string;group_id:string;completed:string[];updated_at?:number };
type TaskStat = {task_id:string;learner_id:string;name:string;group_id:string;group_name:string;started_at:number;completed_at:number|null;seconds_spent:number;check_count:number;error_count:number;last_activity_at:number};
type Auth = { role:"guest"|"student"|"admin"; name?:string; completed?:string[]; snapshots?:Record<string,string>; groups?:Group[]; students?:Student[]; errors?:{task_id:string;message:string;count:number}[]; tasks?:Task[]; variantPools?:Record<string,Task[]>; taskStats?:TaskStat[] };
const projectNames:Record<string,string> = {library:"Библиотека",shop:"Магазин",classes:"Запись на занятия"};
const initialStatus:Status = {kind:"idle",text:"Результат появится после выполнения запроса."};

function glossaryExample(term:string){const examples:Record<string,string>={SELECT:"SELECT name FROM students;",WHERE:"SELECT name FROM students WHERE age > 18;",JOIN:"SELECT * FROM students JOIN enrollments ON students.id = enrollments.student_id;",UPDATE:"UPDATE students SET city = 'Тула' WHERE id = 1;",DELETE:"DELETE FROM students WHERE id = 1;","CREATE TABLE":"CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT);","ALTER TABLE":"ALTER TABLE students ADD COLUMN city TEXT;"}; return examples[term]||`-- Пример: ${term}`;}
function errorWord(count:number){const n=Math.abs(count)%100,last=n%10;if(n>10&&n<20)return "ошибок";if(last===1)return "ошибка";if(last>=2&&last<=4)return "ошибки";return "ошибок";}
function idbGet():Promise<Record<string,unknown>> { try{const saved=localStorage.getItem("sql-trainer:guest");if(saved)return Promise.resolve(JSON.parse(saved) as Record<string,unknown>);}catch{} return new Promise(resolve=>{ try{const req=indexedDB.open("sql-trainer",1); req.onupgradeneeded=()=>req.result.createObjectStore("state"); req.onerror=()=>resolve({}); req.onsuccess=()=>{ const tx=req.result.transaction("state","readonly"); const get=tx.objectStore("state").get("guest"); get.onsuccess=()=>resolve(get.result||{}); get.onerror=()=>resolve({}); };}catch{resolve({});} }); }
function idbSet(value:Record<string,unknown>):Promise<void> { try{localStorage.setItem("sql-trainer:guest",JSON.stringify(value));}catch{} return new Promise(resolve=>{ try{const req=indexedDB.open("sql-trainer",1); req.onupgradeneeded=()=>req.result.createObjectStore("state"); req.onerror=()=>resolve(); req.onsuccess=()=>{ const tx=req.result.transaction("state","readwrite"); tx.objectStore("state").put(value,"guest"); tx.oncomplete=()=>resolve(); tx.onerror=()=>resolve(); };}catch{resolve();} }); }
function encode(bytes:Uint8Array){ let str=""; for(let i=0;i<bytes.length;i+=8192) str+=String.fromCharCode(...bytes.subarray(i,i+8192)); return btoa(str); }
function decode(value:string){ const raw=atob(value); return Uint8Array.from(raw,c=>c.charCodeAt(0)); }
function result(db:Database):Result { const rows=db.exec("SELECT 1 WHERE 0"); return rows[0] || {columns:[],values:[]}; }
function run(db:Database,query:string):Result { const output=db.exec(query); return output.at(-1) || result(db); }
function normalized(res:Result,ordered:boolean){ const rows=res.values.map(row=>JSON.stringify(row)); return JSON.stringify({columns:res.columns,rows:ordered?rows:rows.sort()}); }
function stateOf(db:Database){ const tables=db.exec("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")[0]?.values.map(row=>String(row[0]))||[]; return JSON.stringify({tables:tables.map(name=>({name,columns:db.exec(`PRAGMA table_info("${name.replaceAll('"','""')}")`)[0]?.values,indexes:db.exec(`PRAGMA index_list("${name.replaceAll('"','""')}")`)[0]?.values.map(row=>[row[1],row[2]]),foreignKeys:db.exec(`PRAGMA foreign_key_list("${name.replaceAll('"','""')}")`)[0]?.values,rows:db.exec(`SELECT * FROM "${name.replaceAll('"','""')}"`)[0]?.values.map(row=>JSON.stringify(row)).sort()||[]})),schemaObjects:db.exec("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE type IN ('view','trigger') ORDER BY type,name")[0]?.values||[],customIndexes:db.exec("SELECT name,tbl_name FROM sqlite_master WHERE type='index' AND name NOT LIKE 'sqlite_%' ORDER BY name")[0]?.values||[]}); }
function explainError(error:unknown){ const message=error instanceof Error?error.message:String(error); if(message.includes("no such table")) return "SQLite не нашла таблицу. Сверь имя с деревом базы и проверь, создана ли таблица на предыдущем шаге."; if(message.includes("no such column")) return "SQLite не нашла столбец. Посмотри точные имена столбцов в дереве базы: возможно, опечатка или выбран не тот столбец."; if(message.includes("syntax error")) return "SQLite не смогла разобрать SQL. Проверь запятые, скобки, кавычки и порядок команд рядом с указанной позицией."; if(message.includes("UNIQUE constraint")) return "Нарушено ограничение UNIQUE: такое значение уже есть, а повторы запрещены."; if(message.includes("NOT NULL")) return "Нарушено ограничение NOT NULL: обязательный столбец получил пустое значение."; if(message.includes("FOREIGN KEY constraint")) return "Нарушена связь между таблицами: нельзя сослаться на запись, которой нет."; return "Запрос остановился. Прочитай точный текст SQLite ниже, затем проверь имена и структуру запроса."; }
async function post(body:Record<string,unknown>):Promise<Auth & {error?:string;ok?:boolean;code?:string}> { const response=await fetch("/api/app",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}); return response.json(); }

export default function Home(){
  const [sql,setSql]=useState<SqlJsStatic|null>(null);
  const [auth,setAuth]=useState<Auth>({role:"guest"});
  const [managedTasks,setManagedTasks]=useState<Task[]>(allTasks);
  const [loadedSeeds,setLoadedSeeds]=useState<Record<string,string>>({});
  const [guest,setGuest]=useState<{completed:string[];snapshots:Record<string,string>;drafts:Record<string,string>}>({completed:[],snapshots:{},drafts:{}});
  const [selected,setSelected]=useState("database");
  const [code,setCode]=useState(lessons[0].starter);
  const [output,setOutput]=useState<Result|null>(null);
  const [status,setStatus]=useState<Status>(initialStatus);
  const [hint,setHint]=useState(0);
  const [tab,setTab]=useState<"course"|"review"|"admin">("course");
  const [openTerm,setOpenTerm]=useState("");
  const [showLogin,setShowLogin]=useState(false);
  const [loginMode,setLoginMode]=useState<"student"|"admin">("student");
  const [groupCode,setGroupCode]=useState(""); const [name,setName]=useState(""); const [password,setPassword]=useState("");
  const [groupName,setGroupName]=useState(""); const [saving,setSaving]=useState(false);
  const [editTask,setEditTask]=useState<Task|null>(null); const [termsInput,setTermsInput]=useState("");
  const [editOriginalId,setEditOriginalId]=useState("");
  const [adminSection,setAdminSection]=useState<"groups"|"tasks"|"analytics">("groups");
  const [editVariantIndex,setEditVariantIndex]=useState<number|null>(null);
  const [analyticsGroup,setAnalyticsGroup]=useState("all");
  const [selectedAdminGroup,setSelectedAdminGroup]=useState("");
  const [taskSearch,setTaskSearch]=useState("");
  const [openTaskSection,setOpenTaskSection]=useState(allTasks[0]?.module||"");
  const [importGuest,setImportGuest]=useState(false);
  const [glossaryOpen,setGlossaryOpen]=useState(false);
  const [runtimeError,setRuntimeError]=useState("");
  const draftTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
  const taskTimePending=useRef(0);
  const taskTimeFlush=useRef<Promise<unknown>>(Promise.resolve());
  const task=useMemo(()=>managedTasks.find(x=>x.id===selected)||managedTasks[0]||lessons[0],[selected,managedTasks]);
  const completed=useMemo(()=>auth.role==="student"?auth.completed||[]:guest.completed,[auth.role,auth.completed,guest.completed]);
  const snapshots=useMemo(()=>auth.role==="student"?auth.snapshots||{}:guest.snapshots,[auth.role,auth.snapshots,guest.snapshots]);
  const completedSet=useMemo(()=>new Set(completed),[completed]);
  const taskDraft=guest.drafts[task.id];
  const completedCount=managedTasks.filter(item=>completedSet.has(item.id)).length;
  const nextTask=useMemo(()=>{const sequence=task.project?managedTasks.filter(t=>t.project===task.project):managedTasks.filter(t=>t.module===task.module);const index=sequence.findIndex(t=>t.id===task.id);return sequence.slice(index+1).find(t=>!completedSet.has(t.id))||managedTasks.find(t=>!completedSet.has(t.id));},[task,completedSet,managedTasks]);
  const flushTaskTime=useCallback((taskId:string)=>{const seconds=Math.min(60,Math.floor(taskTimePending.current));taskTimePending.current=Math.max(0,taskTimePending.current-seconds);if(seconds<=0)return taskTimeFlush.current;const request=taskTimeFlush.current.then(()=>post({action:"task-time",taskId,seconds}));taskTimeFlush.current=request.catch(()=>undefined);return request;},[]);
  useEffect(()=>{ initSqlJs({locateFile:()=>"/sql-wasm.wasm"}).then(setSql).catch(()=>setRuntimeError("SQLite не загрузился. Обновите страницу.")); idbGet().then(value=>setGuest({completed:Array.isArray(value.completed)?value.completed as string[]:[],snapshots:(value.snapshots as Record<string,string>)||{},drafts:(value.drafts as Record<string,string>)||{}})); fetch("/api/app").then(r=>r.json() as Promise<Auth>).then(data=>{setAuth(data);if(data.tasks)setManagedTasks(data.tasks);}).catch(()=>{}); },[]);
  // Reset controlled editor state when either the selected task or its restored draft changes.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(()=>{ setCode(taskDraft||task.starter); setOutput(null); setStatus(initialStatus); setHint(0); setOpenTerm(""); },[task.id,task.starter,taskDraft]);
  useEffect(()=>{const profile=task.seedProfile;if(!profile||loadedSeeds[profile])return;fetch(`/api/app?seedProfile=${encodeURIComponent(profile)}`).then(r=>r.json() as Promise<{seed?:string;error?:string}>).then(data=>{if(data.seed)setLoadedSeeds(current=>({...current,[profile]:data.seed!}));else setStatus({kind:"bad",text:data.error||"Учебный набор данных не загрузился."});}).catch(()=>setStatus({kind:"bad",text:"Учебный набор данных не загрузился. Проверьте соединение."}));},[task.seedProfile,task.project,task.seed,loadedSeeds]);
  useEffect(()=>{
    if(auth.role!=="student"||completedSet.has(task.id))return;
    let last=Date.now();
    void post({action:"task-start",taskId:task.id});
    const timer=setInterval(()=>{const now=Date.now();if(document.visibilityState==="visible"&&document.hasFocus())taskTimePending.current+=Math.max(0,Math.round((now-last)/1000));last=now;if(taskTimePending.current>=15)void flushTaskTime(task.id);},5000);
    return ()=>{clearInterval(timer);if(taskTimePending.current>0)void flushTaskTime(task.id);};
  },[auth.role,task.id,completedSet,flushTaskTime]);
  const dbTables=useMemo(()=>{if(!sql)return [];let db:Database|undefined;try{const snapshot=task.project?snapshots[task.project]:undefined;db=snapshot?new sql.Database(decode(snapshot)):new sql.Database();if(!snapshot){db.run(variantSql(task.seedProfile?loadedSeeds[task.seedProfile]||task.seed:task.seed,task.tableMap));prepareVariantDatabase(db,task);}const names=db.exec("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")[0]?.values.map(row=>String(row[0]))||[];return names.map(name=>{const safe=name.replaceAll('"','""');return {name,columns:db!.exec(`PRAGMA table_info("${safe}")`)[0]?.values.map(row=>String(row[1]))||[],rows:db!.exec(`SELECT * FROM "${safe}" LIMIT 8`)[0]?.values||[],foreignKeys:db!.exec(`PRAGMA foreign_key_list("${safe}")`)[0]?.values.map(row=>`${String(row[3])} → ${String(row[2])}.${String(row[4])}`)||[]};});}catch{return [];}finally{db?.close();}},[sql,task,loadedSeeds,snapshots]);
  const saveGuest=useCallback((value:typeof guest)=>{setGuest(value); void idbSet(value);},[]);
  function changeCode(value:string){setCode(value); if(draftTimer.current) clearTimeout(draftTimer.current); const taskId=task.id; draftTimer.current=setTimeout(()=>{setGuest(current=>{const latest={...current,drafts:{...current.drafts,[taskId]:value}};void idbSet(latest);return latest;});},450);}
  function baseFor(t:Task){ const snapshot=t.project?snapshots[t.project]:undefined; return snapshot?new sql!.Database(decode(snapshot)):new sql!.Database(); }
  function prepare(db:Database,t:Task){if(!t.project||!snapshots[t.project]) {db.run(variantSql(t.seedProfile?loadedSeeds[t.seedProfile]||t.seed:t.seed,t.tableMap));prepareVariantDatabase(db,t);}}
  function execute(check:boolean){ if(!sql) return setStatus({kind:"bad",text:"SQLite ещё загружается. Подождите секунду."}); if(task.seedProfile&&!loadedSeeds[task.seedProfile]) return setStatus({kind:"run",text:"Загружаю учебные таблицы и записи. Попробуй через секунду."}); if(!code.trim()) return setStatus({kind:"bad",text:"Введите SQL-запрос."});
    let actual:Database|undefined,expected:Database|undefined;
    try { actual=baseFor(task);prepare(actual,task); expected=baseFor(task);prepare(expected,task);
      if(task.mode!=="state" && !/^\s*(SELECT|WITH)\b/i.test(code)) throw new Error("Для этой задачи нужен запрос SELECT.");
      const actualResult=run(actual,code); setOutput(actualResult);
      if(!check){setStatus({kind:"run",text:"Запрос выполнен. Теперь можно проверить решение."});return;}
      const expectedResult=run(expected,task.solution);
      let matches=task.mode==="state"?stateOf(actual)===stateOf(expected):normalized(actualResult,!!task.ordered)===normalized(expectedResult,!!task.ordered);
      if(task.id==="transaction") matches=matches&&/^\s*BEGIN\b/i.test(code)&&/\bCOMMIT\s*;?\s*$/i.test(code.trim());
      if(task.id==="constraint"){
        const probe=new sql.Database(actual.export());
        const tickets=task.tableMap?.tickets||"tickets";
        const rejected=(statement:string)=>{try{probe.run(statement);return false;}catch{return true;}};
        try{probe.run(`INSERT INTO ${tickets} (id,code,price) VALUES (99,'probe',10)`);}catch{matches=false;}
        matches=matches&&rejected(`INSERT INTO ${tickets} (id,code,price) VALUES (100,'probe',10)`)&&rejected(`INSERT INTO ${tickets} (id,code,price) VALUES (101,'negative',-1)`)&&rejected(`INSERT INTO ${tickets} (id,code,price) VALUES (102,NULL,10)`);
        probe.close();
      }
      if(auth.role==="student")void flushTaskTime(task.id).then(()=>post({action:"task-check",taskId:task.id,correct:matches}));
      if(!matches){setStatus({kind:"bad",text:"Запрос выполнился, но результат пока отличается от цели. Сравни столбцы, строки и условие."}); if(auth.role==="student") void post({action:"attempt",taskId:task.id,message:"Результат отличается"}); return;}
      setStatus({kind:"good",text:"Задание выполнено."});
      const merged=[...new Set([...completed,task.id])]; const updatedSnapshots={...snapshots};
      if(task.project && task.mode==="state") updatedSnapshots[task.project]=encode(actual.export());
      if(auth.role==="student") {setAuth({...auth,completed:merged,snapshots:updatedSnapshots}); void post({action:"progress",completed:[task.id],project:task.project,snapshot:task.project&&task.mode==="state"?updatedSnapshots[task.project]:undefined}).then(data=>{if(data.error)setStatus({kind:"bad",text:"Решение верное, но сохранить прогресс не удалось. Проверьте соединение и повторите."});});}
      else saveGuest({...guest,completed:merged,snapshots:updatedSnapshots});
    } catch(e){ const raw=e instanceof Error?e.message:String(e); const msg=explainError(e);setStatus({kind:"bad",text:msg,rawError:raw});setOutput(null); if(auth.role==="student"){void flushTaskTime(task.id).then(()=>post({action:"task-check",taskId:task.id,correct:false}));void post({action:"attempt",taskId:task.id,message:msg});} }
    finally {actual?.close();expected?.close();}
  }
  function selectTask(id:string){setSelected(id);setTab("course");window.scrollTo({top:0,behavior:"smooth"});}
  async function login(){setSaving(true); const data=await post(loginMode==="admin"?{action:"admin-login",password}:{action:"student-login",name,code:groupCode});setSaving(false);if(data.error)return setStatus({kind:"bad",text:data.error});if(data.role==="admin"){const fresh=await fetch("/api/app").then(r=>r.json() as Promise<Auth>);setAuth(fresh);if(fresh.tasks)setManagedTasks(fresh.tasks);}else{setAuth(data);if(data.tasks)setManagedTasks(data.tasks);}setShowLogin(false);setPassword("");setStatus(initialStatus);if(data.role==="admin")setTab("admin");if(data.role==="student"&&guest.completed.length)setImportGuest(true);}
  async function logout(){await post({action:"logout"});setAuth({role:"guest"});const fresh=await fetch("/api/app").then(r=>r.json() as Promise<Auth>);setManagedTasks(fresh.tasks||allTasks);setTab("course");}
  async function mergeGuest(){
    if(!sql)return;
    setSaving(true);
    try{
      const projectsToImport=Object.keys(guest.snapshots).filter(id=>!auth.snapshots?.[id]);
      for(const project of projectsToImport){
        const db=new sql.Database(decode(guest.snapshots[project]));
        let snapshot:string;
        try{
          const map=Object.assign({},...managedTasks.filter(t=>t.project===project).map(t=>t.tableMap||{})) as Record<string,string>;
          const names=new Set(db.exec("SELECT name FROM sqlite_master WHERE type='table'")[0]?.values.map(row=>String(row[0]))||[]);
          for(const [from,to] of Object.entries(map))if(names.has(from)&&from!==to)db.run(`ALTER TABLE "${from.replaceAll('"','""')}" RENAME TO "${to.replaceAll('"','""')}"`);
          snapshot=encode(db.export());
        }finally{db.close();}
        const saved=await post({action:"progress",project,snapshot});
        if(saved.error)throw new Error(saved.error);
      }
      const data=await post({action:"progress",completed:guest.completed});
      if(data.error)throw new Error(data.error);
      setAuth({...auth,completed:data.completed,snapshots:data.snapshots});setImportGuest(false);
    }catch(error){setStatus({kind:"bad",text:error instanceof Error?error.message:"Не удалось перенести прогресс. Попробуйте ещё раз."});}
    finally{setSaving(false);}
  }
  async function createGroup(){if(!groupName.trim())return;setSaving(true);const data=await post({action:"create-group",name:groupName});setSaving(false);if(data.error)return setStatus({kind:"bad",text:data.error});setGroupName("");const fresh=await fetch("/api/app").then(r=>r.json() as Promise<Auth>);setAuth(fresh);setStatus({kind:"good",text:`Группа создана. Код: ${data.code}`});}
  async function deleteGroup(group:Group){if(!window.confirm(`Удалить группу «${group.name}»? Вместе с ней будут удалены участники, их прогресс и история ошибок.`))return;setSaving(true);const data=await post({action:"delete-group",groupId:group.id});setSaving(false);if(data.error)return setStatus({kind:"bad",text:data.error});const fresh=await fetch("/api/app").then(r=>r.json() as Promise<Auth>);setAuth(fresh);setSelectedAdminGroup(fresh.groups?.[0]?.id||"");setStatus({kind:"good",text:`Группа «${group.name}» удалена.`});}
  async function seedDemoData(){setSaving(true);const data=await post({action:"seed-demo"});setSaving(false);if(data.error)return setStatus({kind:"bad",text:data.error});const fresh=await fetch("/api/app").then(r=>r.json() as Promise<Auth>);setAuth(fresh);if(data.groups?.[0])setSelectedAdminGroup(data.groups[0].id);setStatus({kind:"good",text:"Добавлены две демонстрационные группы и ученики с разным прогрессом."});}
  function startTaskEdit(item?:Task){const next=item?{...item,hints:[...item.hints] as [string,string]}:({id:`teacher-${Date.now()}`,module:"Мои задания",title:"Новое задание",minutes:5,concept:"",terms:[],example:"",prompt:"",starter:"-- Напиши SQL-запрос",solution:"",hints:["",""],seed:"",mode:"query",variantEligible:true} as Task);setEditTask(next);setEditVariantIndex(null);setEditOriginalId(item?.id||"");setTermsInput(next.terms.join(", "));if(item)setOpenTaskSection(item.module);}
  function startVariantEdit(base:Task,index:number,variant?:Task){const next=variant?{...variant,hints:[...variant.hints] as [string,string]}:{...base,hints:[...base.hints] as [string,string]};setEditTask(next);setEditVariantIndex(index);setEditOriginalId(base.id);setTermsInput(next.terms.join(", "));}
  async function saveTask(){if(!editTask)return;const taskToSave={...editTask,terms:termsInput.split(",").map(x=>x.trim()).filter(Boolean)};setSaving(true);const data=editVariantIndex!==null?await post({action:"save-variant",taskId:editOriginalId,variantIndex:editVariantIndex,task:taskToSave}):await post({action:"save-task",task:taskToSave,originalId:editOriginalId});setSaving(false);if(data.error)return setStatus({kind:"bad",text:data.error});if(data.tasks)setManagedTasks(data.tasks);if(data.variantPools)setAuth(current=>({...current,variantPools:data.variantPools}));setEditTask(null);setEditVariantIndex(null);setEditOriginalId("");setStatus({kind:"good",text:editVariantIndex!==null?"Альтернативный вариант сохранён.":"Задание сохранено и добавлено в маршрут."});}
  async function deleteTask(id:string){setSaving(true);const data=await post({action:"delete-task",taskId:id});setSaving(false);if(data.error)return setStatus({kind:"bad",text:data.error});if(data.tasks){setManagedTasks(data.tasks);if(selected===id)setSelected(data.tasks[0]?.id||"database");}setEditTask(null);setStatus({kind:"good",text:"Задание убрано из маршрута."});}
  const adminGroups=auth.groups||[];
  const adminStudents=auth.students||[];
  const selectedGroup=adminGroups.find(group=>group.id===selectedAdminGroup)||adminGroups[0];
  const groupStudents=selectedGroup?adminStudents.filter(student=>student.group_id===selectedGroup.id):[];
  const activeTaskIds=new Set(managedTasks.map(item=>item.id));
  const groupStats={count:groupStudents.length,averageCompleted:groupStudents.length?groupStudents.reduce((sum,student)=>sum+student.completed.filter(id=>activeTaskIds.has(id)).length,0)/groupStudents.length:0,averageProgress:groupStudents.length?Math.round(groupStudents.reduce((sum,student)=>sum+student.completed.filter(id=>activeTaskIds.has(id)).length/Math.max(1,managedTasks.length)*100,0)/groupStudents.length):0,started:groupStudents.filter(student=>student.completed.some(id=>activeTaskIds.has(id))).length,finished:groupStudents.filter(student=>managedTasks.length>0&&managedTasks.every(item=>student.completed.includes(item.id))).length};
  const taskSections=[...new Set(managedTasks.map(item=>item.module))].map(module=>({module,tasks:managedTasks.filter(item=>item.module===module)}));
  const stats=(auth.taskStats||[]).filter(item=>analyticsGroup==="all"||item.group_id===analyticsGroup);
  const taskAnalytics=managedTasks.map(item=>{const records=stats.filter(row=>row.task_id===item.id);const completedRecords=records.filter(row=>row.completed_at!==null);return {task:item,starts:records.length,completed:completedRecords.length,errors:records.reduce((sum,row)=>sum+row.error_count,0),checks:records.reduce((sum,row)=>sum+row.check_count,0),avgSeconds:records.length?Math.round(records.reduce((sum,row)=>sum+row.seconds_spent,0)/records.length):0,avgCompletion:completedRecords.length?Math.round(completedRecords.reduce((sum,row)=>sum+row.seconds_spent,0)/completedRecords.length):0,latest:completedRecords.sort((a,b)=>(b.completed_at||0)-(a.completed_at||0))[0],latestActivity:records.sort((a,b)=>b.last_activity_at-a.last_activity_at)[0]};});
  const stopCounts=new Map<string,number>();for(const student of adminStudents.filter(item=>analyticsGroup==="all"||item.group_id===analyticsGroup)){const stop=managedTasks.find(item=>!student.completed.includes(item.id));if(stop)stopCounts.set(stop.id,(stopCounts.get(stop.id)||0)+1);}
  const hardTasks=[...taskAnalytics].sort((a,b)=>b.errors-a.errors||b.starts-a.starts).slice(0,8);
  const topicAnalytics=[...new Set(managedTasks.map(item=>item.module))].map(module=>{const items=taskAnalytics.filter(item=>item.task.module===module);return {module,errors:items.reduce((sum,item)=>sum+item.errors,0),starts:items.reduce((sum,item)=>sum+item.starts,0),seconds:items.reduce((sum,item)=>sum+item.avgSeconds*item.starts,0),stops:items.reduce((sum,item)=>sum+(stopCounts.get(item.task.id)||0),0)}}).sort((a,b)=>b.errors-a.errors||b.stops-a.stops);
  const stopTasks=managedTasks.map(item=>({task:item,count:stopCounts.get(item.id)||0})).filter(item=>item.count>0).sort((a,b)=>b.count-a.count).slice(0,8);
  const filteredTaskSections=taskSections.map(section=>({...section,tasks:section.tasks.filter(item=>`${item.title} ${item.module} ${item.prompt}`.toLocaleLowerCase("ru").includes(taskSearch.toLocaleLowerCase("ru")))})).filter(section=>section.tasks.length>0);

  const taskEditor=editTask&&<article className="task-editor admin-card"><div className="task-editor-head"><div><div className="eyebrow">КАРТОЧКА ЗАДАНИЯ</div><h2>{editVariantIndex!==null?"Вариант "+(editVariantIndex+1):editOriginalId?"Настройки задания":"Новое задание"}</h2><p className="task-seed-note">{editVariantIndex!==null?"Измените формулировку, данные или ответ для этой версии.":"Изменения вступят в силу для маршрута после сохранения."}</p></div><button className="text-button" onClick={()=>editVariantIndex!==null?startTaskEdit(managedTasks.find(item=>item.id===editOriginalId)):setEditTask(null)}>{editVariantIndex!==null?"← К вариантам":"Закрыть"}</button></div><div className="task-form-grid"><label>ID задания<input disabled={editVariantIndex!==null} value={editTask.id} onChange={e=>setEditTask({...editTask,id:e.target.value})}/></label><label>Раздел<input value={editTask.module} onChange={e=>setEditTask({...editTask,module:e.target.value})}/></label><label>Название<input value={editTask.title} onChange={e=>setEditTask({...editTask,title:e.target.value})}/></label><label>Минут<input type="number" min="1" max="240" value={editTask.minutes} onChange={e=>setEditTask({...editTask,minutes:Number(e.target.value)})}/></label><label>Термины через запятую<input value={termsInput} onChange={e=>setTermsInput(e.target.value)}/></label><label>Проект<select value={editTask.project||""} onChange={e=>setEditTask({...editTask,project:e.target.value||undefined})}><option value="">Без проекта</option><option value="library">Библиотека</option><option value="shop">Магазин</option><option value="classes">Запись на занятия</option></select></label><label className="wide">Задание<textarea rows={3} value={editTask.prompt} onChange={e=>setEditTask({...editTask,prompt:e.target.value})}/></label><label className="wide">Объяснение темы<textarea rows={3} value={editTask.concept} onChange={e=>setEditTask({...editTask,concept:e.target.value})}/></label><label className="wide">Пример SQL<textarea rows={2} value={editTask.example} onChange={e=>setEditTask({...editTask,example:e.target.value})}/></label><label className="wide">Стартовый запрос<textarea rows={2} value={editTask.starter} onChange={e=>setEditTask({...editTask,starter:e.target.value})}/></label><label className="wide">Эталонный ответ<textarea rows={3} value={editTask.solution} onChange={e=>setEditTask({...editTask,solution:e.target.value})}/></label><label>Подсказка 1<textarea rows={2} value={editTask.hints[0]} onChange={e=>setEditTask({...editTask,hints:[e.target.value,editTask.hints[1]]})}/></label><label>Подсказка 2<textarea rows={2} value={editTask.hints[1]} onChange={e=>setEditTask({...editTask,hints:[editTask.hints[0],e.target.value]})}/></label><label className="wide">Подготовка базы данных (SQL)<textarea rows={4} value={editTask.seed} onChange={e=>setEditTask({...editTask,seed:e.target.value})}/></label><label>Учебный набор<select value={editTask.seedProfile||""} onChange={e=>setEditTask({...editTask,seedProfile:e.target.value?e.target.value as NonNullable<Task["seedProfile"]>:undefined})}><option value="">Использовать SQL-подготовку выше</option><option value="parking-spots">Парковка · места</option><option value="parking-database">Парковка · полная база</option><option value="case-sx4">Практика · SX4</option><option value="sugar-success">Практика · Сахарный успех</option><option value="globus-budget">Практика · Глобус</option></select></label><label>Проверка<select value={editTask.mode||"query"} onChange={e=>setEditTask({...editTask,mode:e.target.value as "query"|"state"})}><option value="query">Результат SELECT</option><option value="state">Изменение структуры/данных</option></select></label><label className="task-check"><input type="checkbox" checked={editTask.variantEligible!==false} onChange={e=>setEditTask({...editTask,variantEligible:e.target.checked})}/> Создавать альтернативы</label><label className="task-check"><input type="checkbox" checked={!!editTask.ordered} onChange={e=>setEditTask({...editTask,ordered:e.target.checked})}/> Учитывать порядок строк</label></div>{editOriginalId&&editVariantIndex===null&&<section className="variant-editor"><div className="eyebrow">АЛЬТЕРНАТИВЫ ДЛЯ УЧЕНИКОВ</div><p>{editTask.variantEligible===false?"Это вводное задание: для него варианты отключены.":"Ученики получают базовую формулировку или одну из альтернатив. Для одного сквозного проекта назначается общий вариант."}</p>{editTask.variantEligible!==false&&(auth.variantPools?.[editOriginalId]||[]).map((variant,index)=><article className="variant-row" key={`${editOriginalId}-${index}`}><div><strong>Вариант {index+2}</strong><span>{variant.prompt}</span></div><button className="secondary light" onClick={()=>startVariantEdit(editTask,index+1,variant)}>Просмотреть и изменить</button></article>)}{editTask.variantEligible!==false&&(auth.variantPools?.[editOriginalId]?.length||0)<3&&<button className="secondary light" onClick={()=>startVariantEdit(editTask,(auth.variantPools?.[editOriginalId]?.length||0)+1)}>＋ Создать вариант</button>}</section>}<div className="task-editor-actions"><button className="primary" onClick={saveTask} disabled={saving||!editTask.id.trim()||!editTask.title.trim()||!editTask.prompt.trim()||!editTask.solution.trim()}>{saving?"Сохраняем…":editVariantIndex!==null?"Сохранить вариант":"Сохранить задание"}</button><button className="secondary light" onClick={()=>{setEditTask(null);setEditVariantIndex(null)}}>Отмена</button>{editOriginalId&&editVariantIndex===null&&<button className="danger-button" onClick={()=>deleteTask(editOriginalId)} disabled={saving}>Убрать из маршрута</button>}</div></article>;
  const adminContent=<section className="admin-page"><div className="eyebrow">КАБИНЕТ ПРЕПОДАВАТЕЛЯ</div><h1>Кабинет преподавателя</h1><p className="lead">Управляйте заданиями, группами и прогрессом учеников в одном месте.</p><div className="storage-note"><strong>Как хранятся данные</strong><span>SQL-запросы ученики выполняют в изолированной SQLite в браузере. Хостовая D1 хранит группы, псевдонимы, отметки о выполнении, проектные снимки и ошибки — сами тексты запросов на сервер не отправляются.</span></div><div className="admin-tabs" role="tablist" aria-label="Раздел кабинета"><button role="tab" aria-selected={adminSection==="groups"} className={adminSection==="groups"?"active":""} onClick={()=>setAdminSection("groups")}>Группы и ученики <span>{adminGroups.length}</span></button><button role="tab" aria-selected={adminSection==="tasks"} className={adminSection==="tasks"?"active":""} onClick={()=>setAdminSection("tasks")}>Задания <span>{managedTasks.length}</span></button><button role="tab" aria-selected={adminSection==="analytics"} className={adminSection==="analytics"?"active":""} onClick={()=>setAdminSection("analytics")}>Аналитика</button></div>{adminSection==="groups"?<><div className="admin-section-heading"><div><h2>Учебные группы</h2><p>Откройте группу, чтобы увидеть прогресс каждого участника и средние показатели.</p></div><button className="secondary light" onClick={seedDemoData} disabled={saving}>{saving?"Добавляем…":"Добавить демо-группы и учеников"}</button></div><div className="admin-form"><input aria-label="Название группы" placeholder="Например, 9А · осень" value={groupName} onChange={e=>setGroupName(e.target.value)}/><button className="primary" onClick={createGroup} disabled={saving||!groupName.trim()}>＋ Создать группу</button></div><div className="admin-grid group-cards">{adminGroups.map(group=>{const count=adminStudents.filter(student=>student.group_id===group.id).length;return <button className={`admin-card group-card ${selectedGroup?.id===group.id?"selected":""}`} key={group.id} onClick={()=>setSelectedAdminGroup(group.id)}><span className="eyebrow">КОД ГРУППЫ</span><strong>{group.name}</strong><code>{group.code}</code><span>{count} {count===1?"ученик":count>1&&count<5?"ученика":"учеников"}</span><b>Открыть обзор →</b></button>})}{adminGroups.length===0&&<div className="empty-state">Групп пока нет. Создайте свою или добавьте демонстрационные данные.</div>}</div>{selectedGroup&&<section className="group-overview"><div className="group-overview-heading"><div><div className="eyebrow">ОБЗОР ГРУППЫ</div><h2>{selectedGroup.name}</h2><p>Код для входа учеников: <code>{selectedGroup.code}</code></p></div><div className="group-overview-actions"><span>{groupStats.count} {groupStats.count===1?"участник":groupStats.count>1&&groupStats.count<5?"участника":"участников"}</span><button className="danger-button" onClick={()=>deleteGroup(selectedGroup)} disabled={saving}>Удалить группу</button></div></div><div className="stat-grid"><article><small>СРЕДНИЙ ПРОГРЕСС</small><strong>{groupStats.averageProgress}%</strong><div className="progress-track"><div style={{width:`${groupStats.averageProgress}%`}}/></div></article><article><small>В СРЕДНЕМ ЗАДАНИЙ</small><strong>{groupStats.averageCompleted.toFixed(1)} <i>/ {managedTasks.length}</i></strong></article><article><small>НАЧАЛИ ОБУЧЕНИЕ</small><strong>{groupStats.started} <i>/ {groupStats.count}</i></strong></article><article><small>ПРОШЛИ ВСЁ</small><strong>{groupStats.finished} <i>/ {groupStats.count}</i></strong></article></div><div className="student-overview"><div className="student-overview-head"><strong>Участники</strong><span>Следующее незавершённое задание показывает, где ученик остановился.</span></div>{groupStudents.map(student=>{const done=student.completed.filter(id=>activeTaskIds.has(id)).length;const percent=Math.round(done/Math.max(1,managedTasks.length)*100);const next=managedTasks.find(item=>!student.completed.includes(item.id));const last=managedTasks.filter(item=>student.completed.includes(item.id)).at(-1);const studentCompletedTasks=managedTasks.filter(item=>student.completed.includes(item.id));const studentCompletedStats=(auth.taskStats||[]).filter(row=>row.learner_id===student.id&&row.completed_at!==null);const totalTaskSeconds=studentCompletedStats.reduce((sum,row)=>sum+row.seconds_spent,0);return <article className="student-overview-row" key={student.id}><div className="student-identity"><span className="student-avatar">{student.name.slice(0,1).toUpperCase()}</span><div><strong>{student.name}</strong><small>{student.updated_at?`Активность ${new Date(student.updated_at).toLocaleDateString("ru-RU")}`:"Пока без активности"}</small></div></div><div className="student-progress-cell"><div><strong>{done} / {managedTasks.length}</strong><span>{percent}%</span></div><div className="progress-track"><div style={{width:`${percent}%`}}/></div></div><div className="student-stopped-cell"><small>{done===0?"ЕЩЁ НЕ НАЧАЛ":"СЛЕДУЮЩИЙ ШАГ"}</small><strong>{next?.title||"Все задания пройдены"}</strong><span>{last?`Последнее выполнено: ${last.title}`:"Первое задание маршрута"}</span></div><details className="student-task-times"><summary>Время по заданиям · {studentCompletedStats.length} из {studentCompletedTasks.length} учтено · {Math.floor(totalTaskSeconds/60)} мин</summary>{studentCompletedTasks.length===0?<p>Ученик ещё не завершил задания.</p>:<div>{studentCompletedTasks.map(completedTask=>{const timing=studentCompletedStats.find(row=>row.task_id===completedTask.id);return <div className="student-task-time" key={completedTask.id}><strong>{completedTask.title}</strong><span>{timing?`${Math.floor(timing.seconds_spent/60)} мин ${timing.seconds_spent%60} сек`:"Нет замера"}</span><time>{timing?.completed_at?new Date(timing.completed_at).toLocaleString("ru-RU"):""}</time></div>})}</div>}</details></article>})}{groupStudents.length===0&&<div className="empty-state">В группе пока нет участников. Передайте код ученикам или добавьте демонстрационные данные.</div>}</div></section>}</>:adminSection==="tasks"?<><div className="admin-section-heading"><div><h2>Каталог заданий</h2><p>Нажмите на задание, чтобы открыть его карточку и изменить параметры.</p></div><button className="primary" onClick={()=>startTaskEdit()} disabled={saving}>＋ Новое задание</button></div><div className="task-catalog-toolbar"><label>Поиск заданий<input value={taskSearch} onChange={e=>setTaskSearch(e.target.value)} placeholder="Название, раздел или текст задания"/></label><span>{managedTasks.length} заданий · {taskSections.length} разделов</span></div><div className="task-catalog-layout"><nav className="task-catalog-menu" aria-label="Список заданий">{filteredTaskSections.map(section=><details key={section.module} open={!!taskSearch||openTaskSection===section.module} onToggle={event=>{if(event.currentTarget.open)setOpenTaskSection(section.module);else if(openTaskSection===section.module)setOpenTaskSection("")}}><summary>{section.module}<span>{section.tasks.length}</span></summary>{section.tasks.map(item=><button className={`task-catalog-item ${editTask?.id===item.id?"active":""}`} key={item.id} onClick={()=>startTaskEdit(item)}><span>{item.title}</span><small>{item.minutes} мин. · {item.mode==="state"?"структура/данные":"запрос"}</small></button>)}</details>)}{filteredTaskSections.length===0&&<div className="empty-state">Заданий по этому запросу нет.</div>}</nav><div className="task-catalog-detail">{taskEditor||<div className="task-detail-empty"><span>✎</span><h3>Выберите задание</h3><p>Карточка с настройками появится здесь.</p></div>}</div></div></>:<section className="analytics-view"><div className="admin-section-heading"><div><h2>Аналитика ошибок и времени</h2><p>Сложные задания, точки остановки и время выполнения по попыткам учеников.</p></div><label>Группа<select value={analyticsGroup} onChange={e=>setAnalyticsGroup(e.target.value)}><option value="all">Все группы</option>{adminGroups.map(group=><option key={group.id} value={group.id}>{group.name}</option>)}</select></label></div><div className="stat-grid"><article><small>НАЧАЛИ ЗАДАНИЯ</small><strong>{stats.length}</strong></article><article><small>УСПЕШНЫЕ ЗАВЕРШЕНИЯ</small><strong>{stats.filter(item=>item.completed_at!==null).length}</strong></article><article><small>ОШИБОЧНЫЕ ПРОВЕРКИ</small><strong>{stats.reduce((sum,item)=>sum+item.error_count,0)}</strong></article><article><small>СРЕДНЕЕ ВРЕМЯ НА ЗАДАНИЕ</small><strong>{stats.length?Math.round(stats.reduce((sum,item)=>sum+item.seconds_spent,0)/stats.length/60):0} <i>мин</i></strong></article></div>{stats.length===0?<div className="empty-state">Пока нет измерений. Статистика появится, когда ученики начнут задания в этой версии приложения.</div>:<><div className="analytics-columns"><article className="admin-card"><h3>Чаще вызывают затруднения</h3><p>По числу отмеченных ошибок и проверок.</p><div className="analytics-table-head"><span>Задание</span><span>Ошибки</span><span>Среднее время</span></div>{hardTasks.map(item=><div className="analytics-row" key={item.task.id}><div><strong>{item.task.title}</strong><small>{item.task.module} · {item.starts} начали · {item.checks} проверок · активность {item.latestActivity?new Date(item.latestActivity.last_activity_at).toLocaleString("ru-RU"):"—"}</small></div><b className="analytics-error-count"><span>{item.errors}</span><span>{errorWord(item.errors)}</span></b><span>{Math.round(item.avgSeconds/60)} мин среднее</span></div>)}</article><article className="admin-card"><h3>Темы и места остановки</h3><p>Остановка — первое незавершённое задание в маршруте.</p><div className="analytics-table-head"><span>Тема</span><span>Ошибки</span><span>Остановки</span></div>{topicAnalytics.map(item=><div className="analytics-row" key={item.module}><div><strong>{item.module}</strong><small>{item.starts} стартов · {Math.round(item.seconds/Math.max(1,item.starts)/60)} мин среднее</small></div><b className="analytics-error-count"><span>{item.errors}</span><span>{errorWord(item.errors)}</span></b><span>{item.stops} остановок</span></div>)}<h3>Конкретные задания</h3>{stopTasks.map(item=><div className="analytics-row compact" key={item.task.id}><strong>{item.task.title}</strong><span>{item.count} остановились</span></div>)}</article></div><article className="admin-card completion-history"><h3>Время выполнения заданий</h3><p>Сколько каждый ученик потратил на задание и когда завершил его.</p><div className="completion-time-head"><span>Ученик и группа</span><span>Задание</span><span>Завершено</span><span>Время</span></div>{stats.filter(item=>item.completed_at!==null).sort((a,b)=>(b.completed_at||0)-(a.completed_at||0)).slice(0,50).map((item,index)=>{const task=managedTasks.find(candidate=>candidate.id===item.task_id);return <div className="completion-time-row" key={item.learner_id+item.task_id+index}><div><strong>{item.name}</strong><small>{item.group_name}</small></div><div><strong>{task?.title||item.task_id}</strong><small>{task?.module||""}</small></div><time>{new Date(item.completed_at!).toLocaleString("ru-RU")}</time><b>{Math.floor(item.seconds_spent/60)} мин {item.seconds_spent%60} сек</b></div>})}{stats.every(item=>item.completed_at===null)&&<div className="empty-state">Успешных завершений пока нет. Время появится после того, как ученик выполнит задание.</div>}</article></>}</section>}</section>;
  return <div className="site-shell">
    <header className="topbar"><div className="brand" onClick={()=>setTab("course")} role="button" tabIndex={0}><span className="brand-mark">{`>_`}</span><span>sql<span className="brand-dot">.</span>пространство</span></div><nav className="topnav" aria-label="Основная навигация"><button className={tab==="course"?"selected":""} onClick={()=>setTab("course")}>Задания</button><button className={tab==="review"?"selected":""} onClick={()=>setTab("review")}>Повторение</button></nav><div className="top-actions">{auth.role==="guest"&&<button className="profile" onClick={()=>{setLoginMode("student");setShowLogin(true)}}>Войти в группу</button>}<DropdownMenu><DropdownMenuTrigger asChild><button className="settings-button" aria-label="Настройки"><Settings size={20}/></button></DropdownMenuTrigger><DropdownMenuContent align="end" className="settings-menu">{auth.role==="admin"?<DropdownMenuItem onSelect={()=>setTab("admin")}>Кабинет преподавателя</DropdownMenuItem>:<DropdownMenuItem onSelect={()=>{setLoginMode("admin");setShowLogin(true)}}>Вход преподавателя</DropdownMenuItem>}{auth.role!=="guest"&&<DropdownMenuItem onSelect={logout}>Выйти{auth.name?` · ${auth.name}`:""}</DropdownMenuItem>}</DropdownMenuContent></DropdownMenu></div></header>
    <main className="main-layout"><TaskNavigation tasks={managedTasks} selected={selected} completed={completedSet} onSelect={selectTask}/>
    <div className="content-area">{tab==="admin"&&auth.role==="admin"?adminContent:tab==="review"?<section className="review-page"><h1>Повторение</h1><div className="review-card"><div><h2>Выполненные задания</h2><p>Выбери любое выполненное задание и реши его снова с чистой учебной базой.</p></div></div><div className="review-list">{managedTasks.filter(t=>completedSet.has(t.id)).map(t=><button key={t.id} onClick={()=>selectTask(t.id)}><span>{t.module}</span><strong>{t.title}</strong><b>Повторить</b></button>)}{completedCount===0&&<p>После первого выполненного задания здесь появятся темы для повторения.</p>}</div><h2 className="section-title">Словарь SQL</h2><p className="lead">Термины и подробные объяснения.</p><div className="glossary-grid">{Object.entries(glossary).map(([term,desc])=><article key={term}><strong>{term}</strong><p>{desc}</p><p>{glossaryLong[term]||desc}</p>{!glossaryExample(term).startsWith("-- Пример:")&&<code>{glossaryExample(term)}</code>}</article>)}</div></section>:<><div className="work-heading"><div><div className="eyebrow">{task.project?`ПРАКТИКА · ${projectNames[task.project]}`:task.module}</div><h1>{task.title}</h1></div><div className="lesson-badge">{completedSet.has(task.id)?"✓ Пройдено":"В процессе"}</div></div><div className="workspace-grid"><section className="lesson-card"><div className="card-label">Задание {managedTasks.findIndex(item=>item.id===task.id)+1}{auth.role==="student"&&task.variantIndex?`.${task.variantIndex}`:""}{task.variantEligible===false&&<span className="task-kind">Вводное</span>}</div><p className="task-prompt">{task.prompt}</p><button className="hint-button" onClick={()=>setHint(Math.min(2,hint+1))}>{hint===0?"Подсказка":hint===1?"Следующая подсказка":"Подсказки открыты"}</button>{hint>0&&<div className="hint-box">{task.hints[hint-1]}</div>}{<section className="project-inspector"><div className="inspector-heading"><div><div className="card-label">Учебная база</div><p>Открой таблицу, чтобы увидеть столбцы и данные.</p></div>{task.project&&<span>{projectNames[task.project]}</span>}</div>{task.project&&<div className="project-steps">{managedTasks.filter(t=>t.project===task.project).map((step,i,steps)=><button key={step.id} disabled={i>0&&!completedSet.has(steps[i-1].id)} className={`${step.id===task.id?"current":""} ${completedSet.has(step.id)?"done":""}`} onClick={()=>selectTask(step.id)}><i>{completedSet.has(step.id)?"✓":String(i+1).padStart(2,"0")}</i>{step.title}</button>)}</div>}<div className="db-tree">{dbTables.map(table=><details key={table.name}><summary><span>▤</span> {table.name}<small>{table.columns.length} столбца</small></summary><div className="db-columns">{table.columns.map(column=><code key={column}>{column}</code>)}</div>{table.foreignKeys.map(link=><div className="db-relation" key={link}>↳ связь: {link}</div>)}{table.rows.length>0?<div className="table-wrap"><table><thead><tr>{table.columns.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{table.rows.map((row,i)=><tr key={i}>{row.map((v,j)=><td key={j}>{v===null?<i>NULL</i>:String(v)}</td>)}</tr>)}</tbody></table></div>:<p className="empty-table">Таблица создана, записей пока нет.</p>}</details>)}{dbTables.length===0&&<p className="empty-table">Пока нет таблиц. Создай первую по заданию.</p>}</div></section>}<div className="card-divider"/><div className="card-label">Объяснение</div><p className="task-concept">{task.concept}</p><div className="example-label">Пример</div><pre className="example-code">{task.example}</pre><div className="terms"><div className="example-label">Термины</div><div className="term-buttons">{task.terms.map(term=><button key={term} className={openTerm===term?"active":""} aria-expanded={openTerm===term} aria-controls="term-explanation" title={glossary[term]||""} onClick={()=>setOpenTerm(openTerm===term?"":term)}>{term}<span className="term-chevron" aria-hidden="true"/></button>)}</div>{openTerm&&<div className="term-brief" id="term-explanation"><strong>{openTerm}</strong><p>{glossary[openTerm]||"Термин SQL"}</p><small>Подробное объяснение — в разделе «Повторение».</small></div>}</div></section><section className="editor-card"><div className="editor-top"><div><span className="editor-light"/> <strong>SQL-редактор</strong> <span className="editor-filename">lesson.sql</span></div><span>SQLite</span></div><div className="editor-body"><div className="line-numbers">{code.split("\n").map((_,i)=><div key={i}>{i+1}</div>)}</div><textarea spellCheck={false} aria-label="SQL-редактор" value={code} onChange={e=>changeCode(e.target.value)} onKeyDown={e=>{if((e.metaKey||e.ctrlKey)&&e.key==="Enter"){e.preventDefault();execute(true)}}}/></div><div className="editor-actions"><span>⌘ / Ctrl + Enter — проверить</span><div><button className="secondary" onClick={()=>execute(false)} disabled={!sql}>Запустить</button><button className="primary" onClick={()=>execute(true)} disabled={!sql}>Проверить решение</button></div></div><div className="result-panel"><div className="result-heading"><span>Результат</span><span className={status.kind}>{status.kind==="good"?"Выполнено":status.kind==="bad"?"Ошибка":""}</span></div><p className={`status-text ${status.kind}`} role="status">{runtimeError||status.text}</p>{status.kind==="bad"&&status.rawError&&<pre className="raw-sql-error"><strong>Точный ответ SQLite</strong>{"\n"}{status.rawError}</pre>}{output&&output.columns.length>0&&<div className="table-wrap"><table><thead><tr>{output.columns.map((c,i)=><th key={i}>{c}</th>)}</tr></thead><tbody>{output.values.slice(0,25).map((row,i)=><tr key={i}>{row.map((v,j)=><td key={j}>{v===null?<i>NULL</i>:String(v)}</td>)}</tr>)}</tbody></table></div>}{status.kind==="good"&&<button className="next-button" onClick={()=>nextTask&&selectTask(nextTask.id)}>{nextTask?`Следующий шаг: ${nextTask.title} →`:"Все задания пройдены!"}</button>}</div></section></div><div className="below-work"><button onClick={()=>{if(draftTimer.current)clearTimeout(draftTimer.current);setCode(task.starter);saveGuest({...guest,drafts:{...guest.drafts,[task.id]:task.starter}});setOutput(null);setStatus(initialStatus)}}>Сбросить запрос</button></div></>}</div></main>
    {showLogin&&<div className="modal-backdrop" onClick={()=>setShowLogin(false)}><div className="modal" role="dialog" aria-modal="true" aria-label="Вход" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setShowLogin(false)} aria-label="Закрыть">×</button><div className="brand-mark">{`>_`}</div><div className="eyebrow">{loginMode==="admin"?"КАБИНЕТ":"СОХРАНИТЬ ПРОГРЕСС"}</div><h2>{loginMode==="admin"?"Вход преподавателя":"Войти в группу"}</h2><p>{loginMode==="admin"?"Введите пароль администратора.":"Код группы даст преподаватель. Имя может быть псевдонимом."}</p>{loginMode==="student"?<><label>Код группы<input value={groupCode} onChange={e=>setGroupCode(e.target.value.toUpperCase())} placeholder="XXXXXXXXXX"/></label><label>Имя или псевдоним<input value={name} onChange={e=>setName(e.target.value)} placeholder="Как к тебе обращаться?"/></label><small>Любой, кто знает код группы и имя, сможет открыть этот прогресс. Не используйте личные данные.</small></>:<label>Пароль<input type="password" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==="Enter"&&login()} placeholder="Пароль администратора"/></label>}<button className="primary login-submit" onClick={login} disabled={saving}>{saving?"Проверяем…":"Войти"}</button>{status.kind==="bad"&&<p className="modal-error">{status.text}</p>}<button className="text-button" onClick={()=>{setShowLogin(false);setTab("course")}}>Продолжить без входа</button></div></div>}
    {importGuest&&<div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-label="Перенос прогресса"><div className="brand-mark">↗</div><h2>Перенести гостевой прогресс?</h2><p>В этом браузере уже выполнено {guest.completed.length} заданий. Добавим их в профиль группы. Состояние проектов на сервере сохранится, если оно там уже есть.</p><button className="primary login-submit" onClick={mergeGuest} disabled={saving||!sql}>{saving?"Переносим…":"Перенести прогресс"}</button><button className="text-button" onClick={()=>setImportGuest(false)} disabled={saving}>Оставить отдельно</button>{status.kind==="bad"&&<p className="modal-error">{status.text}</p>}</div></div>}
    {glossaryOpen&&<div className="modal-backdrop" onClick={()=>setGlossaryOpen(false)}><div className="modal glossary-modal" role="dialog" aria-modal="true" aria-label="Словарь SQL" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setGlossaryOpen(false)}>×</button><div className="eyebrow">БЫСТРАЯ ПОДСКАЗКА</div><h2>Словарь SQL</h2><div className="glossary-grid">{task.terms.map(term=><article key={term}><strong>{term}</strong><p>{glossary[term]||"Термин SQL"}</p></article>)}</div></div></div>}
  </div>;
}
